-- Exercise 10 - b
-- Settlements: pending settlements on Sept 30, 2026, ordered by net amount descending

SELECT
    settlement_id,
    delivery_id,
    daily_price_id,
    net_weight_kg,
    price_per_kg_applied,
    deductions_amount,
    gross_amount,
    net_amount,
    settled_at,
    status
FROM 
    pay.settlements
WHERE 
    settlement_id LIKE '%20260930%'
    AND status = 'pending'
ORDER BY 
    net_amount DESC;

